const users = await Promise.all([fetchUser({ userId: 1 }), fetchUser({ userId: 2 }), fetchUser({ userId: 3 })]);

// Process each user to calculate their discount
const discounts = await Promise.all(
  users.map((user) => calculateDiscount({ premium: user.premium, age: user.age }))
);

// Log results and determine the user with the highest discount
let highestDiscountUser = { userName: '', discount: 0, totalUsers: users.length };

for (let i = 0; i < users.length; i++) {
  const { name } = users[i];
  const { discount } = discounts[i];

  // Log the result
  await logResult({ message: `User ${name}: ${discount}` });

  // Update the user with the highest discount if applicable
  if (discount > highestDiscountUser.discount) {
    highestDiscountUser = { userName: name, discount, totalUsers: users.length };
  }
}

// Return the final result
return { action: 'result', value: highestDiscountUser };

